/**
 * ReconcilerTestPanel
 *
 * Interactive testing panel for the document reconciler.
 * Features a **live document view** that updates in real-time as the editor changes,
 * with animated highlights showing reconciliation operations.
 *
 * Features:
 * - Live document structure view (tree + JSON toggle)
 * - Real-time updates via editor subscription
 * - Animated highlights: yellow=INSERT, red=DELETE, blue=UPDATE, violet=MOVE
 * - JSON document input for target reconciliation
 * - Mock stream processing
 * - Operation log with stats
 *
 * @module editor-ai/components/ReconcilerTestPanel
 */

import { useState, useCallback, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  PlayIcon,
  FileJsonIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  CheckCircleIcon,
  XCircleIcon,
  LoaderIcon,
  ZapIcon,
  TreePineIcon,
  CodeIcon,
  PauseIcon,
  ActivityIcon,
  RotateCcwIcon,
} from 'lucide-react'
import { useReconciler } from '../hooks/useReconciler'
import type { EditorId } from '../schemas/editor'
import type { JSONDocument, JSONNode, MergeResult, MergeOp } from '../reconciler'

// =============================================================================
// Types
// =============================================================================

export interface ReconcilerTestPanelProps {
  /** The editor ID this panel operates on (panel-scoped) */
  editorId: EditorId
  /** Whether panel is expanded */
  isOpen: boolean
  /** Toggle open state */
  onToggle: () => void
  /** Width of the panel (default 400) */
  width?: number
}

type ViewMode = 'tree' | 'json'

interface HighlightedIndices {
  inserted: Set<number>
  deleted: Set<number>
  updated: Set<number>
  moved: Set<number>
}

