// =============================================================================
// Document Tree Component (Live View with Highlights)
// =============================================================================

const OP_COLORS = {
  insert: 'oklch(0.75 0.15 90)', // yellow
  delete: 'oklch(0.65 0.2 25)', // red
  update: 'oklch(0.7 0.15 230)', // blue
  move: 'oklch(0.7 0.15 280)', // violet
  noop: 'transparent',
} as const

interface DocumentTreeNodeProps {
  node: JSONNode
  index: number
  depth?: number
  defaultExpanded?: boolean
  highlightType?: 'insert' | 'delete' | 'update' | 'move' | null
}

function DocumentTreeNode({
  node,
  index,
  depth = 0,
  defaultExpanded = true,
  highlightType,
}: DocumentTreeNodeProps) {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded && depth < 2)
  const hasChildren = node.content && node.content.length > 0
  const hasMarks = node.marks && node.marks.length > 0
  const hasAttrs = node.attrs && Object.keys(node.attrs).length > 0

  // Color coding by node type
  const getTypeColor = (type: string) => {
    const colors: Record<string, string> = {
      doc: 'oklch(0.7 0.15 280)', // violet
      paragraph: 'oklch(0.7 0.15 160)', // green
      heading: 'oklch(0.7 0.15 60)', // amber
      text: 'oklch(0.6 0 0)', // gray
      bulletList: 'oklch(0.7 0.15 200)', // cyan
      orderedList: 'oklch(0.7 0.15 200)',
      listItem: 'oklch(0.6 0.1 200)',
      codeBlock: 'oklch(0.7 0.15 30)', // orange
      blockquote: 'oklch(0.6 0.15 300)',
      hardBreak: 'oklch(0.5 0 0)',
    }
    return colors[type] || 'oklch(0.65 0.1 220)'
  }

  const highlightBg = highlightType ? `${OP_COLORS[highlightType]}30` : undefined
  const highlightBorder = highlightType ? OP_COLORS[highlightType] : undefined

  return (
    <motion.div
      className="font-mono"
      style={{ paddingLeft: depth > 0 ? 12 : 0 }}
      initial={highlightType ? { backgroundColor: `${OP_COLORS[highlightType]}50` } : false}
      animate={{ backgroundColor: highlightBg || 'transparent' }}
      transition={{ duration: 1.5, ease: 'easeOut' }}
    >
      {/* Node header */}
      <div
        className="flex items-center gap-1 py-0.5 cursor-pointer hover:bg-white/5 rounded px-1 -mx-1"
        onClick={() => hasChildren && setIsExpanded(!isExpanded)}
        style={{
          borderLeft: highlightBorder ? `2px solid ${highlightBorder}` : undefined,
          paddingLeft: highlightBorder ? 4 : undefined,
        }}
      >
        {/* Expand/collapse arrow */}
        {hasChildren ? (
          <span
            className="w-3 h-3 flex items-center justify-center"
            style={{ color: 'oklch(0.5 0 0)' }}
          >
            {isExpanded ? (
              <ChevronDownIcon className="w-3 h-3" />
            ) : (
              <ChevronRightIcon className="w-3 h-3" />
            )}
          </span>
        ) : (
          <span className="w-3" />
        )}

        {/* Index badge */}
        <span
          className="text-xs px-1 rounded"
          style={{
            background: 'oklch(0.15 0 0)',
            color: 'oklch(0.45 0 0)',
            fontVariantNumeric: 'tabular-nums',
          }}
        >
          {index}
        </span>

        {/* Node type */}
        <span
          className="text-xs font-medium"
          style={{ color: getTypeColor(node.type) }}
        >
          {node.type}
        </span>

        {/* Attrs preview */}
        {hasAttrs && (
          <span
            className="text-xs"
            style={{ color: 'oklch(0.5 0.1 60)' }}
          >
            {JSON.stringify(node.attrs)}
          </span>
        )}

        {/* Text content preview */}
        {node.text && (
          <span
            className="text-xs truncate max-w-[150px]"
            style={{ color: 'oklch(0.7 0 0)' }}
          >
            "{node.text.length > 25 ? node.text.slice(0, 25) + '...' : node.text}"
          </span>
        )}

        {/* Marks badge */}
        {hasMarks && (
          <span
            className="text-xs px-1 rounded"
            style={{
              background: 'oklch(0.6 0.15 280 / 0.2)',
              color: 'oklch(0.65 0.15 280)',
            }}
          >
            {node.marks?.map((m) => m.type).join(', ')}
          </span>
        )}

        {/* Child count */}
        {hasChildren && (
          <span
            className="text-xs"
            style={{ color: 'oklch(0.4 0 0)' }}
          >
            ({node.content?.length})
          </span>
        )}
      </div>

      {/* Children */}
      {isExpanded && hasChildren && (
        <div
          style={{
            borderLeft: '1px solid oklch(0.15 0 0)',
            marginLeft: 6,
          }}
        >
          {node.content?.map((child, idx) => (
            <DocumentTreeNode
              key={idx}
              node={child}
              index={idx}
              depth={depth + 1}
              defaultExpanded={depth < 1}
            />
          ))}
        </div>
      )}
    </motion.div>
  )
}

// =============================================================================
// Live Document View
// =============================================================================

interface LiveDocumentViewProps {
  document: JSONDocument | null
  viewMode: ViewMode
  highlights: HighlightedIndices
  isLive: boolean
  onToggleLive: () => void
  onToggleView: () => void
  lastUpdateMs: number | null
}

function LiveDocumentView({
  document,
  viewMode,
  highlights,
  isLive,
  onToggleLive,
  onToggleView,
  lastUpdateMs,
}: LiveDocumentViewProps) {
  // Determine highlight type for each top-level node
  const getHighlightType = (idx: number): DocumentTreeNodeProps['highlightType'] => {
    if (highlights.inserted.has(idx)) return 'insert'
    if (highlights.deleted.has(idx)) return 'delete'
    if (highlights.updated.has(idx)) return 'update'
    if (highlights.moved.has(idx)) return 'move'
    return null
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div
        className="flex items-center justify-between px-3 py-2 flex-shrink-0"
        style={{ borderBottom: '1px solid oklch(0.1 0 0)' }}
      >
        <div className="flex items-center gap-2">
          <ActivityIcon
            className="w-3.5 h-3.5"
            style={{ color: isLive ? 'oklch(0.7 0.15 160)' : 'oklch(0.4 0 0)' }}
          />
          <span
            className="text-xs font-medium"
            style={{ color: 'oklch(0.6 0 0)' }}
          >
            Live Document
          </span>
          {lastUpdateMs !== null && (
            <span
              className="text-xs"
              style={{ color: 'oklch(0.4 0 0)' }}
            >
              ({lastUpdateMs}ms)
            </span>
          )}
        </div>
        <div className="flex items-center gap-1">
          {/* Tree/JSON toggle */}
          <button
            onClick={onToggleView}
            className="p-1 rounded transition-colors"
            style={{
              background: 'oklch(0.1 0 0)',
              color: 'oklch(0.6 0 0)',
            }}
            title={viewMode === 'tree' ? 'Show JSON' : 'Show Tree'}
          >
            {viewMode === 'tree' ? (
              <CodeIcon className="w-3.5 h-3.5" />
            ) : (
              <TreePineIcon className="w-3.5 h-3.5" />
            )}
          </button>
          {/* Live toggle */}
          <button
            onClick={onToggleLive}
            className="p-1 rounded transition-colors"
            style={{
              background: isLive ? 'oklch(0.7 0.15 160 / 0.2)' : 'oklch(0.1 0 0)',
              color: isLive ? 'oklch(0.7 0.15 160)' : 'oklch(0.5 0 0)',
            }}
            title={isLive ? 'Pause updates' : 'Resume updates'}
          >
            {isLive ? (
              <PauseIcon className="w-3.5 h-3.5" />
            ) : (
              <PlayIcon className="w-3.5 h-3.5" />
            )}
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-auto p-3">
        {!document ? (
          <div
            className="flex items-center justify-center h-full text-xs"
            style={{ color: 'oklch(0.4 0 0)' }}
          >
            No editor view available
          </div>
        ) : viewMode === 'tree' ? (
          <DocumentTreeNode
            node={document}
            index={0}
            depth={0}
            defaultExpanded={true}
            highlightType={null}
          />
        ) : (
          <pre
            className="text-xs overflow-auto whitespace-pre-wrap"
            style={{ color: 'oklch(0.75 0 0)' }}
          >
            {JSON.stringify(document, null, 2)}
          </pre>
        )}
      </div>

      {/* Legend */}
      <div
        className="flex items-center gap-3 px-3 py-2 flex-shrink-0"
        style={{ borderTop: '1px solid oklch(0.08 0 0)' }}
      >
        <span className="text-xs" style={{ color: 'oklch(0.4 0 0)' }}>
          Legend:
        </span>
        <div className="flex items-center gap-1">
          <span
            className="w-2 h-2 rounded-sm"
            style={{ background: OP_COLORS.insert }}
          />
          <span className="text-xs" style={{ color: 'oklch(0.5 0 0)' }}>
            INS
          </span>
        </div>
        <div className="flex items-center gap-1">
          <span
            className="w-2 h-2 rounded-sm"
            style={{ background: OP_COLORS.delete }}
          />
          <span className="text-xs" style={{ color: 'oklch(0.5 0 0)' }}>
            DEL
          </span>
        </div>
        <div className="flex items-center gap-1">
          <span
            className="w-2 h-2 rounded-sm"
            style={{ background: OP_COLORS.update }}
          />
          <span className="text-xs" style={{ color: 'oklch(0.5 0 0)' }}>
            UPD
          </span>
        </div>
        <div className="flex items-center gap-1">
          <span
            className="w-2 h-2 rounded-sm"
            style={{ background: OP_COLORS.move }}
          />
          <span className="text-xs" style={{ color: 'oklch(0.5 0 0)' }}>
            MOV
          </span>
        </div>
      </div>
    </div>
  )
}

// =============================================================================
// Main Component
// =============================================================================

export function ReconcilerTestPanel({
  editorId,
  isOpen,
  onToggle,
  width = 400,
}: ReconcilerTestPanelProps) {
  const reconciler = useReconciler(editorId)

  // Local state
  const [jsonInput, setJsonInput] = useState(
    JSON.stringify(SAMPLE_DOCUMENTS['Simple Paragraph'], null, 2)
  )
  const [selectedSample, setSelectedSample] = useState('Simple Paragraph')
  const [validationError, setValidationError] = useState<string | null>(null)

  // Live document state
  const [liveDocument, setLiveDocument] = useState<JSONDocument | null>(null)
  const [isLive, setIsLive] = useState(true)
  const [viewMode, setViewMode] = useState<ViewMode>('tree')
  const [lastUpdateMs, setLastUpdateMs] = useState<number | null>(null)
  const [highlights, setHighlights] = useState<HighlightedIndices>({
    inserted: new Set(),
    deleted: new Set(),
    updated: new Set(),
    moved: new Set(),
  })

  // Active tab
  const [activeTab, setActiveTab] = useState<'live' | 'input'>('live')

  // Track last update timestamp for latency display
  const lastUpdateTimeRef = useRef<number>(Date.now())

  // Subscribe to document updates (replaces polling)
  useEffect(() => {
    if (!isOpen || !isLive || !reconciler.hasView) {
      return
    }

    // Initial fetch to populate liveDocument
    reconciler.getDocumentJSON().then((doc) => {
      if (doc) {
        setLiveDocument(doc)
        setLastUpdateMs(0) // Initial load, no latency
      }
    })

    // Subscribe to real-time updates
    const unsubscribe = reconciler.subscribeToDocument((doc) => {
      const now = Date.now()
      const elapsed = now - lastUpdateTimeRef.current
      lastUpdateTimeRef.current = now

      setLiveDocument(doc)
      setLastUpdateMs(elapsed)
    })

    return unsubscribe
  }, [isOpen, isLive, reconciler.hasView, reconciler])

  // Handle sample selection
  const handleSelectSample = useCallback((name: string) => {
    setSelectedSample(name)
    setJsonInput(JSON.stringify(SAMPLE_DOCUMENTS[name], null, 2))
    setValidationError(null)
  }, [])

  // Validate and parse JSON
  const parseDocument = useCallback(async (): Promise<JSONDocument | null> => {
    try {
      const parsed = JSON.parse(jsonInput)
      const validated = await reconciler.validateDocument(parsed)
      setValidationError(null)
      return validated
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Invalid JSON'
      setValidationError(msg)
      return null
    }
  }, [jsonInput, reconciler])

  // Apply highlights from merge result
  const applyHighlights = useCallback((ops: readonly MergeOp[]) => {
    const newHighlights: HighlightedIndices = {
      inserted: new Set(),
      deleted: new Set(),
      updated: new Set(),
      moved: new Set(),
    }

    for (const op of ops) {
      switch (op.type) {
        case 'INSERT':
          newHighlights.inserted.add(op.index)
          break
        case 'DELETE':
          newHighlights.deleted.add(op.index)
          break
        case 'UPDATE':
          newHighlights.updated.add(op.index)
          break
        case 'MOVE':
          newHighlights.moved.add(op.fromIndex)
          newHighlights.moved.add(op.toIndex)
          break
      }
    }

    setHighlights(newHighlights)

    // Clear highlights after animation
    setTimeout(() => {
      setHighlights({
        inserted: new Set(),
        deleted: new Set(),
        updated: new Set(),
        moved: new Set(),
      })
    }, 2000)
  }, [])

  // Handle reconcile with preview
  const handleReconcile = useCallback(async () => {
    const doc = await parseDocument()
    if (!doc) return

    try {
      // First compute merge to get ops for highlighting
      const mergeResult = await reconciler.computeMerge(doc)
      if (mergeResult) {
        applyHighlights(mergeResult.ops)
      }

      // Then apply
      await reconciler.reconcileDocument(doc)
    } catch (err) {
      // Error already captured in reconciler.error
    }
  }, [parseDocument, reconciler, applyHighlights])

  // Handle mock stream
  const handleMockStream = useCallback(async () => {
    const doc = await parseDocument()
    if (!doc) return

    // Get ops for highlighting
    const mergeResult = await reconciler.computeMerge(doc)
    if (mergeResult) {
      applyHighlights(mergeResult.ops)
    }

    // Create mock async iterable that yields JSON tokens
    async function* mockStream(): AsyncIterable<string> {
      const json = JSON.stringify(doc)
      const chunkSize = 50
      for (let i = 0; i < json.length; i += chunkSize) {
        yield json.slice(i, i + chunkSize)
        await new Promise((r) => setTimeout(r, 10))
      }
    }

    try {
      await reconciler.processStream(mockStream())
    } catch (err) {
      // Error already captured in reconciler.error
    }
  }, [parseDocument, reconciler, applyHighlights])

  return (
    <div
      className="h-full flex flex-col overflow-hidden flex-shrink-0"
      style={{
        width: isOpen ? width : 0,
        background: 'oklch(0.04 0 0)',
        borderLeft: isOpen ? '1px solid oklch(0.12 0 0)' : 'none',
        transition: 'width 0.2s ease',
      }}
    >
      {isOpen && (
        <>
          {/* Header */}
          <div
            className="flex items-center justify-between px-4 py-3 flex-shrink-0"
            style={{
              borderBottom: '1px solid oklch(0.1 0 0)',
              background: 'oklch(0.05 0 0)',
            }}
          >
            <div className="flex items-center gap-2">
              <FileJsonIcon
                className="w-4 h-4"
                style={{ color: 'oklch(0.6 0.15 280)' }}
              />
              <span
                className="text-sm font-medium"
                style={{ color: 'oklch(0.7 0 0)' }}
              >
                Reconciler
              </span>
              {reconciler.isReconciling && (
                <LoaderIcon
                  className="w-3.5 h-3.5 animate-spin"
                  style={{ color: 'oklch(0.7 0.15 160)' }}
                />
              )}
            </div>

            {/* Status indicator */}
            <div className="flex items-center gap-2">
              {reconciler.hasView ? (
                <span
                  className="flex items-center gap-1 text-xs"
                  style={{ color: 'oklch(0.6 0.15 160)' }}
                >
                  <CheckCircleIcon className="w-3 h-3" />
                  Ready
                </span>
              ) : (
                <span
                  className="flex items-center gap-1 text-xs"
                  style={{ color: 'oklch(0.6 0.15 30)' }}
                >
                  <XCircleIcon className="w-3 h-3" />
                  No view
                </span>
              )}
            </div>
          </div>

          {/* Tab bar */}
          <div
            className="flex px-2 pt-2 flex-shrink-0"
            style={{ borderBottom: '1px solid oklch(0.08 0 0)' }}
          >
            <button
              onClick={() => setActiveTab('live')}
              className="px-3 py-1.5 text-xs font-medium rounded-t transition-colors"
              style={{
                background: activeTab === 'live' ? 'oklch(0.08 0 0)' : 'transparent',
                color: activeTab === 'live' ? 'oklch(0.8 0 0)' : 'oklch(0.5 0 0)',
                borderBottom:
                  activeTab === 'live' ? '2px solid oklch(0.6 0.15 280)' : '2px solid transparent',
              }}
            >
              <span className="flex items-center gap-1.5">
                <ActivityIcon className="w-3 h-3" />
                Live Doc
              </span>
            </button>
            <button
              onClick={() => setActiveTab('input')}
              className="px-3 py-1.5 text-xs font-medium rounded-t transition-colors"
              style={{
                background: activeTab === 'input' ? 'oklch(0.08 0 0)' : 'transparent',
                color: activeTab === 'input' ? 'oklch(0.8 0 0)' : 'oklch(0.5 0 0)',
                borderBottom:
                  activeTab === 'input' ? '2px solid oklch(0.6 0.15 280)' : '2px solid transparent',
              }}
            >
              <span className="flex items-center gap-1.5">
                <FileJsonIcon className="w-3 h-3" />
                Target Input
              </span>
            </button>
          </div>

          {/* Tab content */}
          <div className="flex-1 min-h-0 overflow-hidden">
            {activeTab === 'live' ? (
              <LiveDocumentView
                document={liveDocument}
                viewMode={viewMode}
                highlights={highlights}
                isLive={isLive}
                onToggleLive={() => setIsLive(!isLive)}
                onToggleView={() => setViewMode(viewMode === 'tree' ? 'json' : 'tree')}
                lastUpdateMs={lastUpdateMs}
              />
            ) : (
              <div className="flex flex-col h-full">
                {/* Sample selector */}
                <div
                  className="px-3 py-2 flex-shrink-0"
                  style={{ borderBottom: '1px solid oklch(0.08 0 0)' }}
                >
                  <label
                    className="block text-xs mb-1.5"
                    style={{ color: 'oklch(0.5 0 0)' }}
                  >
                    Sample Documents
                  </label>
                  <select
                    value={selectedSample}
                    onChange={(e) => handleSelectSample(e.target.value)}
                    className="w-full px-2.5 py-1.5 rounded text-sm"
                    style={{
                      background: 'oklch(0.08 0 0)',
                      color: 'oklch(0.85 0 0)',
                      border: '1px solid oklch(0.12 0 0)',
                    }}
                  >
                    {Object.keys(SAMPLE_DOCUMENTS).map((name) => (
                      <option key={name} value={name}>
                        {name}
                      </option>
                    ))}
                  </select>
                </div>

                {/* JSON Input */}
                <div className="flex-1 flex flex-col min-h-0 px-3 py-2">
                  <label
                    className="block text-xs mb-1.5"
                    style={{ color: 'oklch(0.5 0 0)' }}
                  >
                    Target JSON Document
                  </label>
                  <textarea
                    value={jsonInput}
                    onChange={(e) => {
                      setJsonInput(e.target.value)
                      setValidationError(null)
                    }}
                    className="flex-1 min-h-[150px] p-3 rounded text-sm font-mono resize-none"
                    style={{
                      background: 'oklch(0.06 0 0)',
                      color: 'oklch(0.85 0 0)',
                      border: validationError
                        ? '1px solid oklch(0.6 0.15 30)'
                        : '1px solid oklch(0.12 0 0)',
                    }}
                    spellCheck={false}
                  />
                  {validationError && (
                    <p
                      className="text-xs mt-1"
                      style={{ color: 'oklch(0.6 0.15 30)' }}
                    >
                      {validationError}
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Actions */}
          <div
            className="px-3 py-3 flex gap-2 flex-shrink-0"
            style={{ borderTop: '1px solid oklch(0.1 0 0)' }}
          >
            <button
              onClick={handleReconcile}
              disabled={reconciler.isReconciling || !reconciler.hasView}
              className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2 rounded text-sm font-medium transition-all"
              style={{
                background:
                  reconciler.hasView && !reconciler.isReconciling
                    ? 'oklch(0.6 0.15 280)'
                    : 'oklch(0.15 0 0)',
                color:
                  reconciler.hasView && !reconciler.isReconciling
                    ? 'oklch(0.98 0 0)'
                    : 'oklch(0.4 0 0)',
                cursor:
                  reconciler.isReconciling || !reconciler.hasView
                    ? 'not-allowed'
                    : 'pointer',
              }}
            >
              <PlayIcon className="w-3.5 h-3.5" />
              Reconcile
            </button>

            <button
              onClick={handleMockStream}
              disabled={reconciler.isReconciling || !reconciler.hasView}
              className="flex items-center justify-center gap-1.5 px-3 py-2 rounded text-sm transition-all"
              style={{
                background: 'oklch(0.1 0 0)',
                color: 'oklch(0.7 0 0)',
                border: '1px solid oklch(0.15 0 0)',
                cursor:
                  reconciler.isReconciling || !reconciler.hasView
                    ? 'not-allowed'
                    : 'pointer',
              }}
              title="Process as mock stream"
            >
              <ZapIcon className="w-3.5 h-3.5" />
              Stream
            </button>

            <button
              onClick={reconciler.clearState}
              disabled={!reconciler.lastResult && !reconciler.error}
              className="flex items-center justify-center gap-1.5 px-3 py-2 rounded text-sm transition-all"
              style={{
                background: 'oklch(0.1 0 0)',
                color: 'oklch(0.5 0 0)',
                border: '1px solid oklch(0.15 0 0)',
                cursor:
                  !reconciler.lastResult && !reconciler.error
                    ? 'not-allowed'
                    : 'pointer',
              }}
              title="Clear results"
            >
              <RotateCcwIcon className="w-3.5 h-3.5" />
            </button>
          </div>

          {/* Results */}
          <AnimatePresence>
            {reconciler.lastResult && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="flex-shrink-0 overflow-hidden"
                style={{ borderTop: '1px solid oklch(0.1 0 0)' }}
              >
                <div className="px-3 py-3">
                  {/* Success/Failure indicator */}
                  <div
                    className="flex items-center gap-2 mb-2"
                    style={{
                      color: reconciler.lastResult.success
                        ? 'oklch(0.6 0.15 160)'
                        : 'oklch(0.6 0.15 30)',
                    }}
                  >
                    {reconciler.lastResult.success ? (
                      <CheckCircleIcon className="w-4 h-4" />
                    ) : (
                      <XCircleIcon className="w-4 h-4" />
                    )}
                    <span className="text-sm font-medium">
                      {reconciler.lastResult.success ? 'Success' : 'Failed'}
                    </span>
                    <span
                      className="text-xs ml-auto"
                      style={{ color: 'oklch(0.5 0 0)' }}
                    >
                      {reconciler.lastResult.durationMs}ms
                    </span>
                  </div>

                  {/* Stats */}
                  <div className="flex flex-wrap gap-1.5">
                    <StatBadge
                      label="INS"
                      value={reconciler.lastResult.stats.inserted}
                      color={OP_COLORS.insert}
                    />
                    <StatBadge
                      label="DEL"
                      value={reconciler.lastResult.stats.deleted}
                      color={OP_COLORS.delete}
                    />
                    <StatBadge
                      label="UPD"
                      value={reconciler.lastResult.stats.updated}
                      color={OP_COLORS.update}
                    />
                    <StatBadge
                      label="MOV"
                      value={reconciler.lastResult.stats.moved}
                      color={OP_COLORS.move}
                    />
                    <StatBadge
                      label="NOOP"
                      value={reconciler.lastResult.stats.unchanged}
                      color="oklch(0.5 0 0)"
                    />
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Error display */}
          <AnimatePresence>
            {reconciler.error && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="flex-shrink-0 overflow-hidden"
              >
                <div
                  className="px-3 py-2 text-xs"
                  style={{
                    background: 'oklch(0.15 0.1 30)',
                    color: 'oklch(0.7 0.15 30)',
                  }}
                >
                  <strong>Error:</strong> {reconciler.error}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </>
      )}
    </div>
  )
}

export default ReconcilerTestPanel
